reactiveclass Ping(pong): {
	knownrebecs { 
		Pong pong;
	}
	statevars {
		int count;
	}

	Ping() {
		count = 0;
	}

	msgsrv initial() {
		// No automatic start here; StartMessage will be sent from main
	}

	msgsrv StartMessage() {
		// println("Ping started the game!");
		pong.PingMessage();
	}

	msgsrv PongMessage() {
		count = count + 1;
		// println("Ping received pong #" + count);
		if (count >= 10) {
			pong.StopMessage();
			// println("Ping stopped");
			// context.stop(self) -> no more behavior
		} else {
			pong.PingMessage();
		}
	}
}

